{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회의 병목에 맞는 개선 수단을 선택할 수 있는지 평가한다. 실행 계획에서 파악한 문제와 조회 조건에 맞는 인덱스를 추가한 판단의 연결을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓의 운영 화면에서 신고 목록 조회가 느렸고, 실행 계획에서 신고 테이블과 판매글 테이블을 매번 전체 조인하는 것을 확인했다.",
          "task": "신고 목록 조회 쿼리에 조회 조건에 맞는 인덱스를 추가하고 조인 순서를 정리했다.",
          "action": "조회 조건에 맞는 인덱스를 추가한 근거를 당시 확인한 병목과 연결해 설명한다.",
          "result": "선택한 인덱스가 해당 조회의 불필요한 탐색을 줄이는 데 적합하다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "조회 조건에 맞는 인덱스를 추가한 판단 근거",
          "인덱스 선택을 뒷받침하는 조회 조건의 특성",
          "인덱스 선택과 당시 조회 병목의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리의 실행 계획을 확인하셨을 때, 조회 조건에 맞는 인덱스를 추가한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "조회 조건의 특성과 병목을 연결해 인덱스를 추가한 근거를 구체적으로 설명한다.",
            "선택한 인덱스가 해당 조회의 탐색 부담을 줄일 수 있는 이유를 기술적으로 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 조건이나 탐색량을 근거로 인덱스를 추가했다고 답하지만 당시 쿼리와의 연결이 일반적이다.",
            "인덱스가 조회에 도움이 되는 이유는 타당하나 해당 인덱스를 선택한 근거의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "조회 속도가 빨라졌다는 결과만 반복하고 인덱스를 추가한 판단 근거를 설명하지 못한다.",
            "인덱스는 항상 조회를 빠르게 한다는 일반론에 머물거나 조회 조건과 맞지 않는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류에서 확인한 원인을 같은 장애의 재발을 막는 판단으로 연결할 수 있는지 평가한다. 스케줄러 중복 실행 경험에서 배포 체크리스트에 스케줄러 항목을 넣은 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받았고, 로그를 시간순으로 확인해 스케줄러가 서버 두 대에서 동시에 실행되는 것을 찾았다.",
          "task": "잠금 키를 두는 방식으로 수정했고, 이후 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "배포 체크리스트에 스케줄러 항목을 넣은 근거를 중복 실행의 재발 위험과 연결해 설명한다.",
          "result": "스케줄러 항목을 배포 점검에 포함하는 것이 같은 장애의 반복을 막는 데 적합하다고 판단한 이유를 설명한다."
        },
        "expectedEvidence": [
          "배포 체크리스트에 스케줄러 항목을 넣은 판단 근거",
          "그 판단을 뒷받침한 스케줄러 중복 실행의 재발 위험",
          "스케줄러 항목과 같은 장애의 재발 방지 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 서버 두 대의 스케줄러 중복 실행을 로그로 찾으셨을 때, 배포 체크리스트에 스케줄러 항목을 넣은 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "스케줄러 중복 실행의 재발 위험을 근거로 배포 체크리스트에 항목을 넣은 이유를 구체적으로 설명한다.",
            "해당 항목을 배포 점검에 포함하는 것이 같은 장애의 반복을 막는 데 도움이 되는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "재발 방지를 위해 스케줄러 항목을 넣었다고 답하지만 중복 실행 위험과의 연결이 일반적이다.",
            "배포 점검에 포함할 필요성은 설명하지만 해당 장애에 맞는 판단 근거의 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 항목을 넣었다는 사실만 반복하고 그 판단의 근거를 설명하지 못한다.",
            "체크리스트는 중요하다는 일반론이나 잠금 구현 설명에 머물러 해당 항목을 넣은 이유에 답하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "인터뷰에서 나온 요청을 요구사항으로 구체화할 때 개발 범위를 정하는 판단을 검증한다. 요구사항의 목적과 제약을 개발 범위 조정에 연결한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "개발 범위를 조정한 근거를 인터뷰에서 파악한 요청과 당시의 제약에 연결해 설명한다.",
          "result": "설명한 근거가 조정한 개발 범위와 어떤 점에서 부합하는지 설명한다."
        },
        "expectedEvidence": [
          "개발 범위를 조정한 구체적인 판단 근거",
          "범위 판단을 뒷받침한 요청의 목적과 필요성",
          "범위 판단 당시 고려한 제약이나 우선순위"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 쓰셨을 때, 개발 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "한 사례에 집중해 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "개발 범위를 조정한 근거를 구체적으로 제시하고 해당 근거와 범위 판단의 연결을 명확하게 설명한다.",
            "요청의 목적과 필요성, 제약이나 우선순위 중 판단에 사용한 정보를 들어 범위 조정의 타당성을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "개발 범위를 조정한 근거를 제시하지만 필요성이나 실현 가능성 등 일반적인 설명에 머문다.",
            "판단에 사용한 정보를 일부 제시하지만 그 정보가 범위 조정으로 이어진 연결은 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실만 반복하고 개발 범위를 조정한 근거는 답하지 못한다.",
            "범위 판단과 관련 없는 도구 사용이나 협업 태도만 설명해 조정의 타당성을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름에서 발생할 예외 상황을 화면설계에 반영하는 판단을 검증한다. 예약·취소·알림 흐름의 어떤 조건을 예외 상황으로 다루었는지 그 설계 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름을 다뤘다.",
          "task": "기획 담당으로 흐름과 예외 상황을 포함한 화면설계서 28장을 Figma로 작성했다.",
          "action": "예외 상황을 설계한 근거를 해당 상황의 발생 조건과 화면에서 필요한 동작에 연결해 설명한다.",
          "result": "설명한 근거에 비추어 예외 상황 설계가 기능 흐름의 어떤 불명확함을 줄이는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황을 설계한 구체적인 판단 근거",
          "설계 근거가 된 예외 상황의 발생 조건",
          "해당 조건에서 필요한 화면 동작에 관한 판단"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름을 화면설계서에 담으셨을 때, 예외 상황을 설계한 근거는 무엇이었나요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황을 설계한 근거를 실제로 다룬 발생 조건과 연결해 구체적으로 설명한다.",
            "해당 조건에서 필요한 화면 동작을 들어 예외 상황 설계의 타당성을 명확하게 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 설계한 근거를 제시하지만 사용자 혼란 방지 등 일반적인 필요성에 머문다.",
            "예외 발생 조건이나 필요한 화면 동작을 일부 설명하지만 설계 근거와의 연결은 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실만 반복하고 설계한 근거는 답하지 못한다.",
            "화면 수나 Figma 사용법만 설명해 예외 상황 설계의 타당성을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 그대로 투약하지 않고 확인이 필요한 처방으로 판단할 수 있는지 검증한다. 평소와 다른 진통제 용량을 보고 투약을 멈춘 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 맡았으며 해당 처방의 투약을 멈추고 담당의에게 확인했다.",
          "action": "당시 어떤 정보 때문에 처방 용량을 의심했고 투약을 멈춰야 한다고 판단했는지 설명한다.",
          "result": "처방 용량의 차이가 확인 전 투약을 보류할 이유가 된다는 판단을 설명한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 판단한 구체적인 근거",
          "당시 처방 용량을 의심하는 데 사용한 비교 정보",
          "용량 차이를 단순한 처방 변경으로 받아들이지 않은 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 경험을 본인의 말로 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "당시 처방 용량과 비교한 정보를 구체적으로 제시하며 투약 중단의 근거를 설명한다.",
            "평소와 다른 용량을 확인 없이 투약해서는 안 된다고 판단한 이유를 환자 안전과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 많은 처방 용량을 투약 중단의 근거로 제시하지만 비교 정보의 설명이 제한적이다.",
            "확인되지 않은 용량이라 투약을 멈췄다는 판단은 드러나지만 그 이유는 일반적인 안전 원칙 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈췄다는 사실만 반복하고 당시 판단의 근거를 제시하지 못한다.",
            "나중에 입력 오류로 확인된 결과만 제시하거나 처방은 무조건 따라야 한다는 설명으로 당시 중단 판단을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 간호에 필요한 정보를 다음 근무자에게 빠짐없이 전달할 수 있는지 검증한다. 진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 선택한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 QI 활동에서 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 사고 보고서에서 확인했다.",
          "task": "낙상 고위험 환자 인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "두 정보를 인수인계 항목으로 고른 이유를 당시 환자 간호와 정보 전달의 필요성에 연결해 설명한다.",
          "result": "선택한 항목이 다음 근무자의 환자 상태 이해와 간호의 연속성에 필요한 이유를 설명한다."
